const crypto = require('crypto');

// A chave mestra agora será idêntica à do outro fluxo
const MASTER_KEY = $input.first().json.master_key_transito || "";

return $input.all().map(item => {
    try {
        const encryptedData = $('Traz chave de API').first().json.chave_api;

        if (!encryptedData || !encryptedData.includes(':')) {
            throw new Error("Formato de chave inválido ou dado não encontrado no banco.");
        }

        // Separa o IV do texto criptografado de forma mais direta
        const [ivHex, encryptedHex] = encryptedData.split(':');

        // Cria o decifrador (o IV precisa ser transformado de volta em Buffer)
        const decipher = crypto.createDecipheriv('aes-256-cbc', MASTER_KEY, Buffer.from(ivHex, 'hex'));

        // Decifra convertendo direto de 'hex' para 'utf8' (texto limpo original)
        let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
        decrypted += decipher.final('utf8');

        // Chave pronta para uso!
        item.json.api_key_final = decrypted;

    } catch (e) {
        item.json.error_desc = "Erro técnico na descriptografia: " + e.message;
    }

    return item;
});

